(()=>{
 const EDGE='https://houvoogshtllqbsbckqr.supabase.co/functions/v1/ngo-records';
 async function request(resource,body){const key=localStorage.getItem('ngo-report-desk-workspace-v1');if(!key)return{records:[]};const r=await fetch(EDGE+'?resource='+resource,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','X-Workspace-Key':key},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(20000)});const d=await r.json();if(!r.ok)throw Error(d.error||'Could not load records.');return d;}
 const el=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;return n;};
 async function contacts(){try{const {records}=await request('contacts');$('saved-contacts').replaceChildren();$('contacts-status').textContent=records.length?records.length+' saved donors':'Donor contacts appear here after recording a donation.';for(const d of records){const row=el('div','');row.className='donation-row';row.append(el('strong',d.name),el('p',d.whatsapp?'WhatsApp · '+d.whatsapp:d.email?'Gmail · '+d.email:'No delivery contact'));const label=el('label',' Receive approved reports automatically');const check=document.createElement('input');check.type='checkbox';check.checked=d.receives_reports;check.onchange=async()=>{try{await request('contacts',{id:d.id,receives_reports:check.checked});}catch(e){check.checked=!check.checked;$('contacts-status').textContent=e.message;}};label.prepend(check);row.append(label);$('saved-contacts').append(row);}}catch(e){$('contacts-status').textContent=e.message;}}
 async function activity(){try{const {records}=await request('notifications');$('notification-list').replaceChildren();$('notifications-status').textContent=records.length?'Recent automatic deliveries':'No automatic deliveries queued yet.';for(const d of records)$('notification-list').append(el('p',`${d.document_type==='receipt'?'Receipt + thank-you':'Donor report'} · ${d.channel} · ${d.status==='sent'?'accepted by provider':d.status==='uncertain'?'needs review':d.status} · ${new Date(d.created_at).toLocaleString()}`));}catch(e){$('notifications-status').textContent=e.message;}}
 window.runAutomaticNotifications=async()=>{
  const key=localStorage.getItem('ngo-report-desk-workspace-v1');if(!key)return{accepted:0};let accepted=0,uncertain=0;
  for(let batch=0;batch<10;batch++){const r=await fetch('/api/notifications',{method:'POST',headers:{'Content-Type':'application/json','X-Workspace-Key':key},body:'{}',signal:AbortSignal.timeout(200000)});const d=await r.json();if(!r.ok)throw Error(d.error||'Automatic delivery unavailable.');accepted+=d.accepted;uncertain+=d.uncertain;if(d.processed<3)break;}
  return{accepted,uncertain};
 };
 $('refresh-contacts').onclick=contacts;$('refresh-notifications').onclick=activity;
 window.addEventListener('hashchange',()=>{if(location.hash==='#share'){contacts();activity();}});if(location.hash==='#share'){contacts();activity();}
})();
